import{_ as n,a0 as o,w as p,s,ao as d,I as i,x as a,a1 as t,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"如何在 Ubuntu/CentOS7.1/Fedora22 上安裝 Plex  Media Server | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu/CentOS7.1/Fedora22 上安裝 Plex  Media Server | LCTT (201507) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu/CentOS7.1/Fedora22 上安裝 Plex  Media Server | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu/CentOS7.1/Fedora22 上安裝 Plex  Media Server | LCTT (201507) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201507/Install Plex Media Server On Ubuntu or CentOS 7.1 or Fedora 22","title":"如何在 Ubuntu/CentOS7.1/Fedora22 上安裝 Plex  Media Server","tag":"201507","desc":""},"relativePath":"201507/Install Plex Media Server On Ubuntu or CentOS 7.1 or Fedora 22.md","filePath":"[post].md"}'),x={name:"201507/Install Plex Media Server On Ubuntu or CentOS 7.1 or Fedora 22.md"};function u(b,e,m,h,P,S){const r=o("Link");return p(),s("div",null,[e[16]||(e[16]=d(`<h1 id="如何在-ubuntu-centos7-1-fedora22-上安裝-plex-media-server" tabindex="-1">如何在 Ubuntu/CentOS7.1/Fedora22 上安裝 Plex Media Server <a class="header-anchor" href="#如何在-ubuntu-centos7-1-fedora22-上安裝-plex-media-server" aria-label="Permalink to “如何在 Ubuntu/CentOS7.1/Fedora22 上安裝 Plex  Media Server”">​</a></h1><p>在本文中我們將會向你展示如何容易地在主流的最新Linux發行版上安裝Plex Media Server。在Plex安裝成功後你將可以使用你的中央式家庭媒體播放系統，該系統能讓多個Plex播放器App共享它的媒體資源，並且該系統允許你設置你的環境，增加你的設備以及設置一個可以一起使用Plex的用户組。讓我們首先在Ubuntu15.04上開始Plex的安裝。</p><h3 id="基本的系統資源" tabindex="-1">基本的系統資源 <a class="header-anchor" href="#基本的系統資源" aria-label="Permalink to “基本的系統資源”">​</a></h3><p>系統資源主要取決於你打算用來連接服務的設備類型和數量， 所以根據我們的需求我們將會在一個單獨的服務器上使用以下系統資源。</p><table width="666" style="height:181px;"><tbody><tr><td width="670" colspan="2"><b>Plex Media Server</b></td></tr><tr><td width="236"><b>基礎操作系統</b></td><td width="425">Ubuntu 15.04 / CentOS 7.1 / Fedora 22 Work Station</td></tr><tr><td width="236"><b>Plex Media Server</b></td><td width="425">Version 0.9.12.3.1173-937aac3</td></tr><tr><td width="236"><b>RAM 和 CPU</b></td><td width="425">1 GB  , 2.0 GHZ</td></tr><tr><td width="236"><b>硬盤</b></td><td width="425">30 GB</td></tr></tbody></table><h3 id="在ubuntu-15-04上安裝plex-media-server-0-9-12-3" tabindex="-1">在Ubuntu 15.04上安裝Plex Media Server 0.9.12.3 <a class="header-anchor" href="#在ubuntu-15-04上安裝plex-media-server-0-9-12-3" aria-label="Permalink to “在Ubuntu 15.04上安裝Plex Media Server 0.9.12.3”">​</a></h3><p>我們現在準備開始在Ubuntu上安裝Plex Media Server，讓我們從下面的步驟開始來讓Plex做好準備。</p><h4 id="步驟-1-系統更新" tabindex="-1">步驟 1: 系統更新 <a class="header-anchor" href="#步驟-1-系統更新" aria-label="Permalink to “步驟 1: 系統更新”">​</a></h4><p>用root權限登錄你的服務器。確保你的系統是最新的，如果不是就使用下面的命令。</p><pre><code>root@ubuntu-15:~#apt-get update
</code></pre><h4 id="步驟-2-下載最新的plex-media-server包" tabindex="-1">步驟 2: 下載最新的Plex Media Server包 <a class="header-anchor" href="#步驟-2-下載最新的plex-media-server包" aria-label="Permalink to “步驟 2: 下載最新的Plex Media Server包”">​</a></h4>`,11)),i("p",null,[e[1]||(e[1]=a("創建一個新目錄，用wget命令從",-1)),t(r,{href:"https://plex.tv/"},{default:l(()=>[...e[0]||(e[0]=[a("Plex官網",-1)])]),_:1}),e[2]||(e[2]=a("下載為Ubuntu提供的.deb包並放入該目錄中。",-1))]),e[17]||(e[17]=d(`<pre><code>root@ubuntu-15:~# cd /plex/
root@ubuntu-15:/plex#
root@ubuntu-15:/plex# wget https://downloads.plex.tv/plex-media-server/0.9.12.3.1173-937aac3/plexmediaserver_0.9.12.3.1173-937aac3_amd64.deb
</code></pre><h4 id="步驟-3-安裝plex-media-server的debian包" tabindex="-1">步驟 3: 安裝Plex Media Server的Debian包 <a class="header-anchor" href="#步驟-3-安裝plex-media-server的debian包" aria-label="Permalink to “步驟 3: 安裝Plex Media Server的Debian包”">​</a></h4><p>現在在相同的目錄下執行下面的命令來開始debian包的安裝， 然後檢查plexmediaserver服務的狀態。</p><pre><code>root@ubuntu-15:/plex# dpkg -i plexmediaserver_0.9.12.3.1173-937aac3_amd64.deb
</code></pre><hr><pre><code>root@ubuntu-15:~# service plexmediaserver status
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/plex-status.png" alt="Plexmediaserver Service"></p><h3 id="在ubuntu-15-04上設置plex-media-web應用" tabindex="-1">在Ubuntu 15.04上設置Plex Media Web應用 <a class="header-anchor" href="#在ubuntu-15-04上設置plex-media-web應用" aria-label="Permalink to “在Ubuntu 15.04上設置Plex  Media Web應用”">​</a></h3><p>讓我們在你的本地網絡主機中打開web瀏覽器， 並用你的本地主機IP以及端口32400來打開Web界面，並完成以下步驟來配置Plex。</p><pre><code>http://172.25.10.179:32400/web
http://localhost:32400/web
</code></pre><h4 id="步驟-1-登錄前先註冊" tabindex="-1">步驟 1: 登錄前先註冊 <a class="header-anchor" href="#步驟-1-登錄前先註冊" aria-label="Permalink to “步驟 1: 登錄前先註冊”">​</a></h4><p>在你訪問到Plex Media Server的Web界面之後， 確保註冊並填上你的用户名和密碼來登錄。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/PMS-Login.png" alt="Plex Sign In"></p><h4 id="輸入你的pin碼來保護你的plex-media用户" tabindex="-1">輸入你的PIN碼來保護你的Plex Media用户#### <a class="header-anchor" href="#輸入你的pin碼來保護你的plex-media用户" aria-label="Permalink to “輸入你的PIN碼來保護你的Plex  Media用户####”">​</a></h4><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/333.png" alt="Plex User Pin"></p><p>現在你已經成功的在Plex Media下配置你的用户。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/3333.png" alt="Welcome To Plex"></p><h3 id="在設備上而不是本地服務器上打開plex-web應用" tabindex="-1">在設備上而不是本地服務器上打開Plex Web應用 <a class="header-anchor" href="#在設備上而不是本地服務器上打開plex-web應用" aria-label="Permalink to “在設備上而不是本地服務器上打開Plex Web應用”">​</a></h3><p>如我們在Plex Media主頁看到的提示“你沒有權限訪問這個服務”。 這説明我們跟服務器計算機不在同個網絡。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/33.png" alt="Plex Server Permissions"></p><p>現在我們需要解決這個權限問題，以便我們通過設備訪問服務器而不是隻能在服務器上訪問。通過完成下面的步驟完成。</p><h3 id="設置ssh隧道使windows系統可以訪問到linux服務器" tabindex="-1">設置SSH隧道使Windows系統可以訪問到Linux服務器 <a class="header-anchor" href="#設置ssh隧道使windows系統可以訪問到linux服務器" aria-label="Permalink to “設置SSH隧道使Windows系統可以訪問到Linux服務器”">​</a></h3><p>首先我們需要建立一條SSH隧道以便我們訪問遠程服務器資源，就好像資源在本地一樣。 這僅僅是必要的初始設置。</p><p>如果你正在使用Windows作為你的本地系統，Linux作為服務器，那麼我們可以參照下圖通過Putty來設置SSH隧道。 （LCTT譯註: 首先要在Putty的Session中用Plex服務器IP配置一個SSH的會話，才能進行下面的隧道轉發規則配置。 然後點擊“Open”，輸入遠端服務器用户名密碼， 來保持SSH會話連接。）</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/ssh-tunnel.png" alt="Plex SSH Tunnel"></p><p><strong>一旦你完成SSH隧道設置:</strong></p><p>打開你的Web瀏覽器窗口並在地址欄輸入下面的URL。</p><pre><code>http://localhost:8888/web
</code></pre><p>瀏覽器將會連接到Plex服務器並且加載與服務器本地功能一致的Plex Web應用。 同意服務條款並開始。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/5.png" alt="Agree to Plex term"></p><p>現在一個功能齊全的Plex Media Server已經準備好添加新的媒體庫、頻道、播放列表等資源。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/8.png" alt="PMS Settings"></p><h3 id="在centos-7-1上安裝plex-media-server-0-9-12-3" tabindex="-1">在CentOS 7.1上安裝Plex Media Server 0.9.12.3 <a class="header-anchor" href="#在centos-7-1上安裝plex-media-server-0-9-12-3" aria-label="Permalink to “在CentOS 7.1上安裝Plex Media Server 0.9.12.3”">​</a></h3><p>我們將會按照上述在Ubuntu15.04上安裝Plex Media Server的步驟來將Plex安裝到CentOS 7.1上。</p><p>讓我們從安裝Plex Media Server開始。</p><h4 id="步驟1-安裝plex-media-server" tabindex="-1">步驟1: 安裝Plex Media Server <a class="header-anchor" href="#步驟1-安裝plex-media-server" aria-label="Permalink to “步驟1: 安裝Plex Media Server”">​</a></h4><p>為了在CentOS7.1上安裝Plex Media Server，我們需要從Plex官網下載rpm安裝包。 因此我們使用wget命令來將rpm包下載到一個新的目錄下。</p><pre><code>[root@linux-tutorials ~]# cd /plex
[root@linux-tutorials plex]# wget https://downloads.plex.tv/plex-media-server/0.9.12.3.1173-937aac3/plexmediaserver-0.9.12.3.1173-937aac3.x86_64.rpm
</code></pre><h4 id="步驟2-安裝rpm包" tabindex="-1">步驟2: 安裝RPM包 <a class="header-anchor" href="#步驟2-安裝rpm包" aria-label="Permalink to “步驟2: 安裝RPM包”">​</a></h4><p>在完成安裝包完整的下載之後， 我們將會使用rpm命令在相同的目錄下安裝這個rpm包。</p><pre><code>[root@linux-tutorials plex]# ls
plexmediaserver-0.9.12.3.1173-937aac3.x86_64.rpm
[root@linux-tutorials plex]# rpm -i plexmediaserver-0.9.12.3.1173-937aac3.x86_64.rpm
</code></pre><h4 id="步驟3-啓動plexmediaservice" tabindex="-1">步驟3: 啓動Plexmediaservice <a class="header-anchor" href="#步驟3-啓動plexmediaservice" aria-label="Permalink to “步驟3: 啓動Plexmediaservice”">​</a></h4><p>我們已經成功地安裝Plex Media Server, 現在我們只需要重啓它的服務然後讓它永久地啓用。</p><pre><code>[root@linux-tutorials plex]# systemctl start plexmediaserver.service
[root@linux-tutorials plex]# systemctl enable plexmediaserver.service
[root@linux-tutorials plex]# systemctl status plexmediaserver.service
</code></pre><h3 id="在centos-7-1上設置plex-media-web應用" tabindex="-1">在CentOS-7.1上設置Plex Media Web應用 <a class="header-anchor" href="#在centos-7-1上設置plex-media-web應用" aria-label="Permalink to “在CentOS-7.1上設置Plex  Media Web應用”">​</a></h3><p>現在我們只需要重複在Ubuntu上設置Plex Web應用的所有步驟就可以了。 讓我們在Web瀏覽器上打開一個新窗口並用localhost或者Plex服務器的IP來訪問Plex Media Web應用。</p><pre><code>http://172.20.3.174:32400/web
http://localhost:32400/web
</code></pre><p>為了獲取服務的完整權限你需要重複創建SSH隧道的步驟。 在你用新賬户註冊後我們將可以訪問到服務的所有特性，並且可以添加新用户、添加新的媒體庫以及根據我們的需求來設置它。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/plex-devices-centos.png" alt="Plex Device Centos"></p><h3 id="在fedora-22工作站上安裝plex-media-server-0-9-12-3" tabindex="-1">在Fedora 22工作站上安裝Plex Media Server 0.9.12.3 <a class="header-anchor" href="#在fedora-22工作站上安裝plex-media-server-0-9-12-3" aria-label="Permalink to “在Fedora 22工作站上安裝Plex Media Server 0.9.12.3”">​</a></h3><p>下載和安裝Plex Media Server步驟基本跟在CentOS 7.1上安裝的步驟一致。我們只需要下載對應的rpm包然後用rpm命令來安裝它。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/plex-on-fedora.png" alt="PMS Installation"></p><h3 id="在fedora-22工作站上配置plex-media-web應用" tabindex="-1">在Fedora 22工作站上配置Plex Media Web應用 <a class="header-anchor" href="#在fedora-22工作站上配置plex-media-web應用" aria-label="Permalink to “在Fedora 22工作站上配置Plex  Media Web應用”">​</a></h3><p>我們在（與Plex服務器）相同的主機上配置Plex Media Server，因此不需要設置SSH隧道。只要在你的Fedora 22工作站上用Plex Media Server的默認端口號32400打開Web瀏覽器並同意Plex的服務條款即可。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/Plex-Terms.png" alt="Plex Agreement"></p><p><em>歡迎來到Fedora 22工作站上的Plex Media Server</em></p><p>讓我們用你的Plex賬户登錄，並且開始將你喜歡的電影頻道添加到媒體庫、創建你的播放列表、添加你的圖片以及享用更多其他的特性。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/create-library.png" alt="Plex Add Libraries"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>我們已經成功完成Plex Media Server在主流Linux發行版上安裝和配置。Plex Media Server永遠都是媒體管理的最佳選擇。 它在跨平台上的設置是如此的簡單，就像我們在Ubuntu,CentOS以及Fedora上的設置一樣。它簡化了你組織媒體內容的工作，並將媒體內容“流”向其他計算機以及設備以便你跟你的朋友分享媒體內容。</p><hr>`,61)),i("p",null,[e[4]||(e[4]=a("via: ",-1)),t(r,{href:"http://linoxide.com/tools/install-plex-media-server-ubuntu-centos-7-1-fedora-22/"},{default:l(()=>[...e[3]||(e[3]=[a("http://linoxide.com/tools/install-plex-media-server-ubuntu-centos-7-1-fedora-22/",-1)])]),_:1})]),i("p",null,[e[8]||(e[8]=a("作者：",-1)),t(r,{href:"http://linoxide.com/author/kashifs/"},{default:l(()=>[...e[5]||(e[5]=[a("Kashif Siddique",-1)])]),_:1}),e[9]||(e[9]=a(" 譯者：",-1)),t(r,{href:"https://github.com/dingdongnigetou"},{default:l(()=>[...e[6]||(e[6]=[a("dingdongnigetou",-1)])]),_:1}),e[10]||(e[10]=a(" 校對：",-1)),t(r,{href:"https://github.com/wxy"},{default:l(()=>[...e[7]||(e[7]=[a("wxy",-1)])]),_:1})]),i("p",null,[e[13]||(e[13]=a("本文由 ",-1)),t(r,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[11]||(e[11]=[a("LCTT",-1)])]),_:1}),e[14]||(e[14]=a(" 原創翻譯，",-1)),t(r,{href:"https://linux.cn/"},{default:l(()=>[...e[12]||(e[12]=[a("Linux中國",-1)])]),_:1}),e[15]||(e[15]=a(" 榮譽推出",-1))])])}const M=n(x,[["render",u]]);export{g as __pageData,M as default};
